"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["61686"],{69606(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.referencia_temporal_fatos.tipo_desconhecido","status":422,"titulo":"Tipo de refer\xeancia temporal fora do cat\xe1logo fechado"},"descricao":{"codigo":"uniplus.selecao.referencia_temporal_fatos.tipo_desconhecido","requisitos":[],"oQueAconteceu":["O `tipo` enviado para a refer\xeancia temporal dos fatos est\xe1 preenchido, mas n\xe3o \xe9 um dos quatro tipos\\ndo cat\xe1logo fechado: `FIM_INSCRICAO`, `INICIO_FASE`, `FIM_FASE` ou `DATA_ESPECIFICA`.","A refer\xeancia temporal dos fatos \xe9 a pol\xedtica, no n\xedvel do processo, que define a refer\xeancia para apurar a faixa\\net\xe1ria do candidato: de onde vem a data em que a idade \xe9 contada. Uma \xfanica pol\xedtica vale para todas\\nas regras do processo que citam a idade. Ela \xe9 dada por um tipo (`FIM_INSCRICAO`, `INICIO_FASE`,\\n`FIM_FASE` ou `DATA_ESPECIFICA`) e, conforme o tipo, por uma data ou por uma fase do cronograma. Para\\nremover a refer\xeancia, o pedido omite o tipo, a data e a fase; o tipo omitido com data ou fase presentes\\n\xe9 recusado antes, na valida\xe7\xe3o do pedido, e n\xe3o chega \xe0s confer\xeancias desta p\xe1gina.","Esta recusa se distingue de\\n[`tipo_obrigatorio`](/erros/uniplus.selecao.referencia_temporal_fatos.tipo_obrigatorio), que \xe9 o tipo em\\nbranco. Com o tipo desconhecido, o sistema n\xe3o confere a data nem a fase. A resposta traz o erro no\\ncampo `tipo`, em `errors[]`."],"comoResolver":["Corrija o `tipo` para um dos quatro valores aceitos, informe a data ou a fase que ele pede e envie a\\ndefini\xe7\xe3o de novo."],"ondeAparece":["Defini\xe7\xe3o da refer\xeancia temporal dos fatos do processo seletivo"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Referencia temporal fatos"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"3bbcc2307827ee8c6dab135295710bb856847f61"}}')}}]);